package ama.transcript;
import ama.contract.IdentityContracts.Actor;import ama.contract.MinutesContracts.*;import ama.config.ConfigArchiveSource;import org.springframework.jdbc.core.JdbcTemplate;import java.util.*;import java.util.function.*;import java.util.concurrent.atomic.AtomicBoolean;
/** Physical production reader boundaries under a genuine complete current graph gate; no business writes. */
public final class LocalRowBudgetCheck {
 static void check(boolean value,String message){if(!value)throw new IllegalStateException(message);}
 static void budgetReject(Runnable action){try{action.run();throw new AssertionError("Budget rejection required");}catch(Failure failed){check(failed.code()==FailureCode.BUDGET_EXCEEDED,"Actual budget rejection required");}}
 static TranscriptAcquisitionBudget limits(long[] usage,int dimension,long change,TranscriptAcquisitionBudget normal){var caps=usage.clone();if(dimension>=0)caps[dimension]+=change;return new TranscriptAcquisitionBudget(caps[0],caps[1],caps[2],caps[3],caps[4],Math.max(1,caps[7]),normal.revisionDepth(),normal.revisionNodes(),normal.tasks());}
 public static Map<String,Object> verify(JdbcTranscriptAuthority authority,Actor actor,String meeting,ConfiguredMinutes settings,Runnable reset,IntSupplier bodyTransfers,IntSupplier metadataQueries){
  JdbcMinutesFactsReader.independent();var j=new JdbcTemplate(authority.dataSource());j.setQueryTimeout(5);var normal=settings.bounds();var ledger=normal.ledger(authority.readBudget(),authority.canonicalBudget(),()->false);var discovery=MinutesGraphDiscovery.discover(authority.dataSource(),meeting,"SAVED_EFFECTIVE",null,normal,authority.readBudget());JdbcMinutesFactsReader.charge(discovery,ledger);var checks=new ArrayList<String>();final long[][] rowUsage={null};
  var captured=authority.transactionRunner().required(()->{
   var gate=JdbcMinutesFactsReader.lockGraph(authority,actor,meeting,discovery,ama.access.MeetingAccess.Action.READ);var scope=authority.minutesReadScope(gate,actor,meeting);var graph=MinutesGraphCapture.captureCurrent(authority,scope,gate,actor,discovery,ledger);String id=(String)graph.discovery().root().get("minutes_revision_id");check(id!=null,"Actual current saved body required");
   var one=normal.ledger(authority.readBudget(),authority.canonicalBudget(),()->false);reset.run();var supplier=new SavedTranscriptRows(j,one,authority.readBudget().maxManifestBytes()).deferRows(Table.MINUTES_REVISION,"id=?","id",1,true,id);check(metadataQueries.getAsInt()>0&&bodyTransfers.getAsInt()==0,"Metadata/admission must precede executeQuery of body");rowUsage[0]=one.usage();var rows=supplier.get();check(rows.size()==1&&bodyTransfers.getAsInt()==1,"One admitted physical current body transfer required");check(Arrays.equals(rowUsage[0],one.usage()),"Owned transfer copies must already be reserved");check(one.usage()[0]>one.usage()[2]&&one.usage()[2]>one.usage()[1],"Actual Chinese and supplementary Unicode metrics required");checks.add("physical-metadata-reserve-before-driver-body-query");
   // Every exact bound is computed from measured actual native MySQL row metadata, not a SQL text fixture.
   for(int dimension:new int[]{0,1,2,3,4,7}){
    reset.run();var exact=limits(rowUsage[0],-1,0,normal).ledger(authority.readBudget(),authority.canonicalBudget(),()->false);var actual=new SavedTranscriptRows(j,exact,authority.readBudget().maxManifestBytes()).rows(Table.MINUTES_REVISION,"id=?","id",1,true,id);check(actual.equals(rows)&&bodyTransfers.getAsInt()==1,"Exact native row boundary must pass");
    reset.run();var under=limits(rowUsage[0],dimension,-1,normal).ledger(authority.readBudget(),authority.canonicalBudget(),()->false);budgetReject(()->new SavedTranscriptRows(j,under,authority.readBudget().maxManifestBytes()).rows(Table.MINUTES_REVISION,"id=?","id",1,true,id));check(bodyTransfers.getAsInt()==0,"Over-bound row must not execute a body query");
   }checks.add("exact-utf8-scalar-utf16-copy-and-response-boundaries");
   reset.run();var stop=new AtomicBoolean();var cancellation=normal.ledger(authority.readBudget(),authority.canonicalBudget(),stop::get);var deferred=new SavedTranscriptRows(j,cancellation,authority.readBudget().maxManifestBytes()).deferRows(Table.MINUTES_REVISION,"id=?","id",1,true,id);stop.set(true);try{deferred.get();throw new AssertionError("Cancelled transfer must reject");}catch(Failure failed){check(failed.code()==FailureCode.CANCELLED,"Actual cancellation required");}check(bodyTransfers.getAsInt()==0,"Cancelled admission must not transfer body");checks.add("cancellation-after-admission-before-body-query");
   reset.run();var twice=rowUsage[0].clone();for(int n=0;n<twice.length;n++)twice[n]*=2;var cumulative=limits(twice,-1,0,normal).ledger(authority.readBudget(),authority.canonicalBudget(),()->false);var reader=new SavedTranscriptRows(j,cumulative,authority.readBudget().maxManifestBytes());reader.rows(Table.MINUTES_REVISION,"id=?","id",1,true,id);reader.rows(Table.MINUTES_REVISION,"id=?","id",1,true,id);budgetReject(()->reader.rows(Table.MINUTES_REVISION,"id=?","id",1,true,id));check(bodyTransfers.getAsInt()==2,"Cumulative bound must reject before a third body query");checks.add("same-ledger-repeated-physical-captures");return graph;
  });
  long[] afterS=ledger.usage();new JdbcMinutesFactsReader(authority,settings.archives(),settings.pin(),normal).prepare(captured,ledger);long[] afterA=ledger.usage();authority.transactionRunner().required(()->{var gate=JdbcMinutesFactsReader.lockGraph(authority,actor,meeting,discovery,ama.access.MeetingAccess.Action.READ);var scope=authority.minutesReadScope(gate,actor,meeting);var fresh=MinutesGraphCapture.captureCurrent(authority,scope,gate,actor,discovery,ledger);check(captured.equals(fresh),"Actual complete current S/F graphs must match");return null;});long[] afterF=ledger.usage();check(afterA[0]>=afterS[0]&&afterF[0]>afterA[0]&&afterF[3]>afterA[3],"S/A/F must reuse the same cumulative ledger");checks.add("genuine-complete-current-graph-S-A-F-shared-ledger");
  return Map.of("checks",checks,"physicalRowUsage",rowUsage[0],"afterS",afterS,"afterA",afterA,"afterF",afterF,"scope","Physical reader exact row + genuine complete graph S/A/F, not every application endpoint");
 }
}
